#include <bits/stdc++.h>
using namespace std;
const string W="LLLLRLRRRRLRLLRRLLLLRRLLRRRRLLRRLRLLRLLRLRLLRRRRLLRLLRRRRLLRRRRLLRLRRRRLRLLLLRRRRLRRLRRRRLLLLRLRRRRLRRRR";
array<bool,1024>legal{};set<int>allowed;vector<string>marks={"LLLL","RRRLLRLLRRRR"};map<pair<int,int>,char>last;set<tuple<string,string,string>>returns;int dx[4]={0,1,0,-1},dy[4]={1,0,-1,0},minstop=0,maximum=0;uint64_t nodes=0,cap=10000000,frontier=0;bool stopped=false;string initial;
int bits(string s){int b=0;for(char c:s)b=(b<<1)+(c=='R');return b;}
void dfs(string&w,int x,int y,int h,int b,bool prev){if(++nodes>cap){stopped=true;return;}maximum=max(maximum,(int)w.size());if(w.size()>=500){frontier++;return;}auto p=make_pair(x,y);auto it=last.find(p);char old=it==last.end()?'?':it->second;for(char c:{'L','R'}){if(c==old)continue;int nb=((b<<1)+(c=='R'))&4095;bool bad=w.size()>=9&&!legal[nb&1023];if(prev&&bad&&!allowed.count(nb&2047))continue;last[p]=c;w.push_back(c);int hh=(h+(c=='R'?1:3))%4;string hit;for(auto&m:marks)if(w.size()>=m.size()&&(nb&((1<<m.size())-1))==bits(m)){hit=m;break;}if(!hit.empty()&&w.size()>minstop){if(!initial.empty())returns.insert({initial,hit,w.substr(0,w.size()-hit.size())});}else dfs(w,x+dx[hh],y+dy[hh],hh,nb,bad);w.pop_back();if(old=='?')last.erase(p);else last[p]=old;if(stopped)return;}}
int main(int argc,char**argv){string labels=argv[1],pre=argv[2],p;stringstream ss(labels);while(getline(ss,p,','))allowed.insert(bits(p));for(int i=0;i<104;i++)legal[bits((W+W).substr(i,10))]=true;string w;dfs(w,0,0,0,0,false);cout<<"initial nodes="<<nodes<<" stopped="<<stopped<<" frontier="<<frontier<<" max="<<maximum<<endl;if(stopped||frontier)return 1;for(auto&m:marks){initial=m;minstop=m.size();last.clear();int x=0,y=0,h=0,b=0;bool prev=false,ok=true;for(char c:m){if(last[{x,y}]==c){ok=false;break;}last[{x,y}]=c;b=((b<<1)+(c=='R'))&4095;h=(h+(c=='R'?1:3))%4;x+=dx[h];y+=dy[h];}if(!ok)continue;prev=m.size()>=10&&!legal[b&1023];w=m;dfs(w,x,y,h,b,prev);}ofstream out(pre+".returns.tsv");for(auto[a,b,w]:returns)out<<a<<' '<<b<<' '<<w<<'\n';cout<<"total nodes="<<nodes<<" stopped="<<stopped<<" frontier="<<frontier<<" max="<<maximum<<" returns="<<returns.size()<<endl;return stopped||frontier;}
